# The same two functions with the routing taken out. Each one carries
# a description, and the model reads the descriptions and picks.
from langchain_core.tools import tool
from langchain_openai import ChatOpenAI


@tool
def search_handbook(query: str) -> str:
    """Look up a passage in the company handbook by what it is about."""
    ...


@tool
def rate_per_mile(service: str) -> float:
    """Today's depot rate in pounds per mile for a named service."""
    ...


model = ChatOpenAI(model="gpt-4o-mini").bind_tools(
    [search_handbook, rate_per_mile]
)

for question in ["my car will not start", "how much to be towed in"]:
    for call in model.invoke(question).tool_calls:
        print(question, "->", call["name"], call["args"])
# my car will not start -> search_handbook
#     {'query': 'car will not start'}
# how much to be towed in -> rate_per_mile {'service': 'tow'}

# No branch and no word list. Neither question repeats a word from the
# descriptions, and both land on the tool that can answer them. A
# third tool is a third function: nothing else changes.
